const origem = $('Code in JavaScript').first().json;
const linhas = Array.isArray(origem.linhas_pdf) ? origem.linhas_pdf : [];

function toNumberBr(value) {
  if (value === null || value === undefined || value === "") return null;
  const str = String(value).trim();
  const num = Number(str.replace(/\./g, "").replace(",", "."));
  return Number.isNaN(num) ? null : num;
}

const produtos = [];

// código do produto: linha só com números, de 8 a 14 dígitos
function isCodigoProduto(linha) {
  return /^\d{8,14}$/.test(String(linha).trim());
}

// linha de valores do item
function extrairDadosLinhaFinal(linha) {
  const texto = String(linha).trim();

  const match = texto.match(
    /(?:\d+[.,]\d+|\d{3})\s+\d{4}\s+(UN|KG|CX|PT|FD|PC)\s+(\d+,\d{2,3})\s+(\d+,\d{2})\s+(\d+,\d{2})\s+(\d+,\d{2})/i
  );

  if (!match) return null;

  return {
    quantidade: Number(String(match[2]).replace(",", ".")),
    valor_unitario: toNumberBr(match[3]),
  };
}

for (let i = 0; i < linhas.length; i++) {
  const linha = String(linhas[i]).trim();

  if (!isCodigoProduto(linha)) continue;

  const codigo = linha;
  let dadosItem = null;

  for (let j = i + 1; j < Math.min(i + 20, linhas.length); j++) {
    const candidato = extrairDadosLinhaFinal(linhas[j]);
    if (candidato) {
      dadosItem = candidato;
      break;
    }

    if (j > i + 1 && isCodigoProduto(linhas[j])) {
      break;
    }
  }

  if (dadosItem) {
    produtos.push({
      codigo,
      quantidade: dadosItem.quantidade,
      valor_unitario: dadosItem.valor_unitario,
    });
  }
}

// remove duplicados
const unicos = [];
const vistos = new Set();

for (const p of produtos) {
  const chave = `${p.codigo}|${p.quantidade}|${p.valor_unitario}`;
  if (!vistos.has(chave)) {
    vistos.add(chave);
    unicos.push(p);
  }
}

return [
  {
    json: {
      produtos: unicos
    }
  }
];

const produtos = $('Preparar Itens Venda').first().json.produtos || [];

return produtos.map(p => ({
  json: {
    codigo: p.codigo,
    quantidade: p.quantidade,
    valor_unitario: p.valor_unitario
  }
}));

const itensOriginais = $items('Explodir produtos').map(item => item.json);
const itensEncontrados = $items('Procurar produto').map(item => item.json);

// microvix_id que realmente voltaram do banco
const encontradosSet = new Set(
  itensEncontrados
    .map(item => String(item.microvix_id || '').trim())
    .filter(Boolean)
);

// compara todos os códigos originais com os encontrados
const naoEncontrados = itensOriginais.filter(item => {
  const codigo = String(item.codigo || '').trim();
  return !encontradosSet.has(codigo);
});

return [
  {
    json: {
      total_originais: itensOriginais.length,
      total_encontrados: itensEncontrados.length,
      total_nao_encontrados: naoEncontrados.length,
      encontrados: itensEncontrados.map(item => String(item.microvix_id || '').trim()),
      nao_encontrados: naoEncontrados.map(item => String(item.codigo || '').trim()),
      todos_encontrados: naoEncontrados.length === 0,
      mensagem:
        naoEncontrados.length === 0
          ? 'Todos os produtos foram encontrados na planilha.'
          : naoEncontrados
              .map(item => `Produto do código ${item.codigo} não foi encontrado na planilha.`)
              .join(' ')
    }
  }
];

const venda = $('Criar Venda').first().json;
const venda_id = venda.id;

// itens originais da nota
const itensOriginais = $items('Explodir produtos').map(item => item.json);

// produtos encontrados no Supabase
const produtosEncontrados = $items('Procurar produto').map(item => item.json);

// índice por microvix_id
const mapaProdutos = new Map();
for (const p of produtosEncontrados) {
  const chave = String(p.microvix_id || '').trim();
  if (chave) {
    mapaProdutos.set(chave, p);
  }
}

return itensOriginais.map(item => {
  const codigo = String(item.codigo || '').trim();
  const quantidade = Number(item.quantidade || 0);
  const preco_unitario = Number(item.valor_unitario || 0);

  const produto = mapaProdutos.get(codigo);

  if (!produto || !produto.id) {
    throw new Error(`Produto não encontrado para o código: ${codigo}`);
  }

  return {
    json: {
      venda_id,
      produto_id: produto.id,
      quantidade,
      preco_unitario,
      desconto: 0,
      valor_total: quantidade * preco_unitario
    }
  };
});
